      "id": "groundwater-depletion-alarm",
      "insight": "Visually distinguish countries with the highest groundwater extraction rates relative to recharge, making unsustainable extraction patterns prominent"
    },
    {
      "id": "precipitation-trend-overlay",
      "insight": "Show the decadal precipitation trend (increasing vs decreasing) alongside the other water stress metrics so viewers can see which water-scarce countries also face declining rainfall"
    },
    {
      "id": "per-capita-freshwater-contrast",
      "insight": "Contrast per-capita freshwater availability between water-rich and water-poor nations to make the orders-of-magnitude difference visually striking"
    }
